/** Cancelled and expired holds are closed — they no longer owe payment. */
export function isClosedBooking(
  booking: Pick<RepBooking, "bookingStatus">,
): boolean {
  return (
    booking.bookingStatus === "cancelled" || booking.bookingStatus === "expired"
  );
}

