export const seedAdminRecords = internalMutation({
  args: {},
  handler: async (ctx) => {
    const reps = await ctx.db.query("agcRepresentatives").collect();
    const rep = reps.find((row) => row.status === "active");
    if (!rep) throw new Error("No active representative");
    const hub = await ctx.db.get(rep.hubId);
    if (!hub) throw new Error("Representative has no hub");
    const now = Date.now();

    const confirmedRegistration = await ctx.db.insert("agcRegistrations", {
      hubId: hub._id,
      repId: rep._id,
      region: hub.region,
      quantity: 1,
      unitPrice: 30,
      currency: "GHS",
      totalAmount: 30,
      paymentMode: "offline",
      paymentStatus: "confirmed",
      paidAt: now,
      confirmedAt: now,
      referenceNumber: "DEVWALKREG-CONFIRMED",
      createdAt: now,
      updatedAt: now,
    });
    const pendingRegistration = await ctx.db.insert("agcRegistrations", {
      hubId: hub._id,
      repId: rep._id,
      region: hub.region,
      quantity: 1,
      unitPrice: 30,
      currency: "GHS",
      totalAmount: 30,
      paymentMode: "offline",
      paymentStatus: "pending_verification",
      referenceNumber: "DEVWALKREG-PENDING",
      createdAt: now,
      updatedAt: now,
    });
    const confirmedBooking = await ctx.db.insert("agcBookings", {
      hubId: hub._id,
      repId: rep._id,
      region: hub.region,
      currency: "GHS",
      totalAmount: 150,
      paymentMode: "offline",
      paymentStatus: "confirmed",
      bookingStatus: "confirmed",
      paidAt: now,
      confirmedAt: now,
      referenceNumber: "DEVWALKSTY-CONFIRMED",
      createdAt: now,
      updatedAt: now,
    });
    const reservedBooking = await ctx.db.insert("agcBookings", {
      hubId: hub._id,
      repId: rep._id,
      region: hub.region,
      currency: "GHS",
      totalAmount: 150,
      paymentMode: "offline",
      paymentStatus: "awaiting_payment",
      bookingStatus: "reserved",
      expiresAt: now + 24 * HOUR,
      referenceNumber: "DEVWALKSTY-RESERVED",
      createdAt: now,
      updatedAt: now,
    });

    return {
      confirmedRegistration,
      pendingRegistration,
      confirmedBooking,
      reservedBooking,
    };
  },
});

