{"kind":"tool","id":"NbMil1I4WuA","toolName":"str_replace","input":{"path":"convex/devWalkthrough.ts","replacements":[{"oldString":"/** Remove everything the walkthrough created, pool counts included. */","newString":"/**
 * An expired booking still holding beds the ledger never released — what the
 * Pools-tab repair button exists to fix (and what the history panel lists).
 */
export const seedLeakedBeds = internalMutation({
  args: {},
  handler: async (ctx) => {
    const reps = await ctx.db.query("agcRepresentatives").collect();
    const rep = reps.find((row) => row.status === "active");
    if (!rep) throw new Error("No active representative");
    const hub = await ctx.db.get(rep.hubId);
    if (!hub) throw new Error("Representative has no hub");
    const now = Date.now();

    const pools = await ctx.db
      .query("agcInventoryPools")
      .withIndex("by_type_scope", (q) =>
        q.eq("accommodationType", "dormitory").eq("scope", "africa"),
      )
      .collect();
    const pool = pools[0];
    if (!pool) throw new Error("No dormitory pool");

    const bookingId = await ctx.db.insert("agcBookings", {
      hubId: hub._id,
      repId: rep._id,
      region: hub.region,
      currency: "GHS",
      totalAmount: 300,
      paymentMode: "offline",
      paymentStatus: "confirmed",
      bookingStatus: "expired",
      referenceNumber: "DEVWALK-LEAKED",
      createdAt: now,
      updatedAt: now,
    });
    await ctx.db.insert("agcBookingLines", {
      bookingId,
      accommodationType: "dormitory",
      quantity: 2,
      unitPrice: 150,
      isBishopRate: false,
    });
    // Reserve + confirm, but never release: the beds stay in `confirmed`.
    await ctx.db.patch(pool._id, { confirmed: pool.confirmed + 2 });
    await ctx.db.insert("agcInventoryLedger", {
      poolId: pool._id,
      accommodationType: "dormitory",
      scope: pool.scope,
      action: "reserve",
      delta: 2,
      bookingId,
      note: "dev walkthrough seed",
      createdAt: now,
    });
    await ctx.db.insert("agcInventoryLedger", {
      poolId: pool._id,
      accommodationType: "dormitory",
      scope: pool.scope,
      action: "confirm",
      delta: 2,
      bookingId,
      note: "dev walkthrough seed",
      createdAt: now,
    });

    return { bookingId, poolConfirmed: pool.confirmed + 2 };
  },
});

/** Remove everything the walkthrough created, pool counts included. */","allowMultiple":false}]}}


