export type ReviewFlagRow = {
  _id: string;
  note: string;
  raisedAt: number;
  raisedBy: string;
  raisedByRole: string | null;
  guestId: string;
  guestName: string;
  gender: string;
  hubName: string;
  accommodationType: string;
  bookingRef: string;
  paymentStatus: string;
  poaStatus: string | null;
  roomName: string | null;
  building: string | null;
  checkInStatus: "checked_in" | "checked_out" | "not_arrived";
};

/** Open review flags for the Accommodation Admin's queue — newest first. */
export const listReviewFlags = query({
  args: { sessionToken: v.string(), limit: v.optional(v.number()) },
  handler: async (ctx, args): Promise<ReviewFlagRow[]> => {
    await requireRole(ctx, args.sessionToken, [...APPROVER_ROLES]);
    const flags = (await ctx.db.query("agcCheckinFlags").collect())
      .filter((flag) => flag.resolvedAt === undefined)
      .sort((a, b) => b.raisedAt - a.raisedAt)
      .slice(0, args.limit ?? 200);
    const guests = new Map((await ctx.db.query("agcGuests").collect()).map(g => [g._id, g]));
    const bookings = new Map((await ctx.db.query("agcBookings").collect()).map(b => [b._id, b]));
    const hubs = new Map((await ctx.db.query("agcHubs").collect()).map(h => [h._id, h.name]));
    const rooms = new Map((await ctx.db.query("agcRooms").collect()).filter(r => !r.deletedAt).map(r => [r._id, r]));
    const openByGuest = new Map<string, Doc<"agcRoomAssignments">>();
    for (const a of await ctx.db.query("agcRoomAssignments").collect()) {
      if (a.endedAt === undefined) openByGuest.set(a.guestId, a);
    }
    const checkInByGuest = new Map<string, Doc<"agcCheckIns">>();
    for (const c of await ctx.db.query("agcCheckIns").collect()) {
      if (!c.correctedAt) checkInByGuest.set(c.guestId, c);
    }
    return flags.map((flag) => {
      const guest = guests.get(flag.guestId);
      const booking = bookings.get(flag.bookingId);
      const currentRoom = rooms.get(openByGuest.get(flag.guestId)?.roomId ?? ("__none__" as Id<"agcRooms">));
      const room = currentRoom ?? (flag.roomId ? rooms.get(flag.roomId) : undefined);
      const checkIn = checkInByGuest.get(flag.guestId);
      return {
        _id: flag._id,
        note: flag.note,
        raisedAt: flag.raisedAt,
        raisedBy: flag.raisedBy,
        raisedByRole: flag.raisedByRole ?? null,
        guestId: flag.guestId,
        guestName: guest ? guestLabel(guest) : "(delegate no longer on file)",
        gender: guest?.gender ?? "",
        hubName: guest ? hubs.get(guest.hubId) ?? "(unknown)" : "(unknown)",
        accommodationType: guest?.accommodationType ?? "",
        bookingRef: booking?.referenceNumber ?? "",
        paymentStatus: booking?.paymentStatus ?? "unknown",
        poaStatus: booking?.poa?.status ?? null,
        roomName: room?.name ?? flag.roomName ?? null,
        building: room?.building ?? null,
        checkInStatus: checkIn ? (checkIn.checkedOutAt ? "checked_out" : "checked_in") : "not_arrived",
      };
    });
  },
});
```

