Rate parsing helper:
```ts
function splitRate(rate?: string) {
  if (!rate) return { amount: null, suffix: "To be confirmed" };
  const match = rate.match(/^(GHS|GH₵|\$|USD)?\s*([\d,]+(?:\.\d+)?)\s*(.*)$/i);
  if (!match) return { amount: null, suffix: rate };
  return { amount: `${match[1] ?? ""} ${match[2]}`.trim(), suffix: match[3] || "per room" };
}
