export const generateReceiptUploadUrl = mutation({
  args: {},
  handler: async (ctx) => await ctx.storage.generateUploadUrl(),
});

export const attachReceipt = mutation({
  args: { referenceNumber: v.string(), email: v.string(), storageId: v.id("_storage") },
  handler: async (ctx, args) => {
    const reference = args.referenceNumber.trim().toUpperCase();
    const order = await ctx.db.query("tourOrders").withIndex("by_reference_number", q => q.eq("referenceNumber", reference)).first();
    if (!order || order.email !== args.email.trim().toLowerCase()) throw new ConvexError("We couldn't match that reference to this email");
    const meta = await ctx.storage.getMetadata(args.storageId);
    if (!meta) throw new ConvexError("Upload not found");
    const isPdf = meta.contentType === "application/pdf";
    const isImage = meta.contentType?.startsWith("image/");
    if (!isPdf && !isImage) throw new ConvexError("Upload a photo or PDF of your receipt");
    if (meta.size > 8 * 1024 * 1024) throw new ConvexError("Receipt must be under 8 MB");
    if (order.receiptStorageId && order.receiptStorageId !== args.storageId) {
      // best-effort delete previous
      if (await ctx.storage.getUrl(order.receiptStorageId)) await ctx.storage.delete(order.receiptStorageId);
    }
    await ctx.db.patch(order._id, { receiptStorageId: args.storageId, receiptUploadedAt: Date.now() });
    await writeAuditLog(ctx, { action: "tour.receipt_upload", entityType: "tourOrders", entityId: order._id, summary: `Receipt uploaded for tour order ${order.referenceNumber}`, metadata: { size: meta.size, contentType: meta.contentType } });
    return { ok: true };
  },
});
```
