```ts
export const getStatus = query({
  args: { referenceNumber: v.string(), email: v.string() },
  handler: async (ctx, args) => {
    const email = args.email.trim().toLowerCase();
    const reference = args.referenceNumber.trim().toUpperCase();
    if (!email || !reference) return null;
    const orders = await ctx.db.query("tourOrders").withIndex("by_email", q => q.eq("email", email)).collect();
    const order = orders.find(o => (o.referenceNumber ?? "").toUpperCase() === reference);
    if (!order) return null;
    const receiptUrl = order.receiptStorageId ? await ctx.storage.getUrl(order.receiptStorageId) : null;
    return {
      referenceNumber: order.referenceNumber ?? reference,
      fullName: order.fullName,
      paymentStatus: order.paymentStatus,
      items: order.items.map(({ label, quantity, unitPrice }) => ({ label, quantity, unitPrice })),
      totalAmount: order.totalAmount,
      currency: order.currency,
      createdAt: order.createdAt,
      receiptUploadedAt: order.receiptUploadedAt ?? null,
      receiptUrl,
    };
  },
});
```
