/**
 * Remove a tour order and its receipt. Admin-only: an order is evidence that
 * money changed hands, so this is a deliberate clean-up (test bookings,
 * duplicates, mistaken entries), not a routine edit. Audited with the details
 * so the deletion can still be accounted for.
 */
export const remove = mutation({
  args: { sessionToken: sessionTokenValidator, id: v.id("tourOrders") },
  handler: async (ctx, args) => {
    const actor = await requireRole(ctx, args.sessionToken, ["admin"]);
    const existing = await ctx.db.get(args.id);
    if (!existing) throw new ConvexError("Tour order not found");

    if (existing.receiptStorageId) {
      // Best effort: the file may already be gone (retention sweep, dashboard).
      if (await ctx.storage.getUrl(existing.receiptStorageId)) {
        await ctx.storage.delete(existing.receiptStorageId);
      }
    }

    await ctx.db.delete(args.id);

    await writeAuditLog(ctx, {
      actorUserId: actor._id,
      actorEmail: actor.email,
      action: "tour_order.delete",
      entityType: "tourOrders",
      entityId: args.id,
      summary: `Deleted tour order ${existing.referenceNumber ?? args.id}`,
      metadata: {
        referenceNumber: existing.referenceNumber ?? null,
        email: existing.email,
        totalAmount: existing.totalAmount,
        currency: existing.currency,
        paymentStatus: existing.paymentStatus,
        items: existing.items.map(i => `${i.label} x${i.quantity}`),
        hadReceipt: Boolean(existing.receiptStorageId),
      },
    });

    return { deleted: true };
  },
});
```
